-- C32 K-Part catalog evidence: SDN and RSD, Cooling/Lubrication/Fuel.
-- Third-party catalog observations only. Do not treat these rows as fitment approval or sellable inventory.
on conflict (evidence_key) do update set
  name=excluded.name,
  source_name=excluded.source_name,
  source_url=excluded.source_url,
  source_note=excluded.source_note,
  updated_at=now()
where public.kpart_catalog_evidence.review_state='CANDIDATE';
